# Property-based testing
@given(st.lists(st.integers()))
def test_reverse_twice_is_identity(lst):
    """Reversing a list twice should give the original list"""
    assert list(reversed(list(reversed(lst)))) == lst

@given(st.lists(st.integers()))
def test_sorted_is_idempotent(lst):
    """Sorting a sorted list should not change it"""
    sorted_once = sorted(lst)
    sorted_twice = sorted(sorted_once)
    assert sorted_once == sorted_twice

@given(st.integers(), st.integers())
def test_addition_commutative(a, b):
    """Addition should be commutative"""
    assert a + b == b + a

@given(st.integers(min_value=1, max_value=100))
def test_percentage_calculation(value):
    """Percentage calculation should be reversible"""
    percentage = value * 0.2
    original = percentage / 0.2
    assert abs(original - value) < 0.0001

